#include "PluginEditor.h"
#include "PluginProcessor.h"
namespace bw{
PluginEditor::PluginEditor(PluginProcessor&p):AudioProcessorEditor(p),processor_(p){juce::Component* components[]={&context_,&conversation_,&proposal_,&status_,&analyze_,&stop_,&confirm_,&focus_,&fork_,&approve_,&arm_};for(auto*c:components)addAndMakeVisible(c);analyze_.onClick=[this]{auto s=processor_.uiSnapshot()->scope;processor_.uiActions().enqueue(ui::UiAction::analyze(s.projectId,s.instanceId,s.clipSid.value_or("")));};stop_.onClick=[this]{processor_.uiActions().enqueue(ui::UiAction::stop(processor_.uiSnapshot()->scope.projectId));};confirm_.onClick=[this]{const auto nonce=processor_.uiSnapshot()->confirmationNonce;if(nonce.empty())processor_.uiActions().enqueue(ui::UiAction::linkConfirmRequest());else processor_.uiActions().enqueue(ui::UiAction::linkConfirmAccept(nonce));};focus_.onClick=[this]{auto s=processor_.uiSnapshot()->scope;processor_.uiActions().enqueue(ui::UiAction::focusSet(s.projectId,s.instanceId,s.clipSid.value_or("")));};fork_.onClick=[this]{auto s=processor_.uiSnapshot();if(s->forkConfirmation){const auto&pending=*s->forkConfirmation;processor_.uiActions().enqueue(ui::UiAction::forkConfirm(pending.sourceProjectId,pending.newProjectId,pending.token));}else{const auto newProjectId=std::string("project-")+juce::Uuid().toString().toStdString();processor_.uiActions().enqueue(ui::UiAction::forkRequest(s->scope.projectId,newProjectId));}};approve_.onClick=[this]{auto s=processor_.uiSnapshot();if(!s->proposal)return;if(s->approvalGrant)processor_.uiActions().enqueue(ui::UiAction::proposalApprove(*s->proposal,*s->approvalGrant));else processor_.uiActions().enqueue(ui::UiAction::proposalApprove(*s->proposal));};arm_.onClick=[this]{auto s=processor_.uiSnapshot();if(!s->proposal)return;if(s->approvalGrant)processor_.uiActions().enqueue(ui::UiAction::phraseArm(*s->proposal,*s->approvalGrant));else processor_.uiActions().enqueue(ui::UiAction::proposalApprove(*s->proposal));};setResizable(true,true);setSize(920,560);startTimerHz(15);timerCallback();}
void PluginEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff15171a));}void PluginEditor::resized(){auto r=getLocalBounds().reduced(12);auto top=r.removeFromTop(48);status_.setBounds(top.removeFromRight(260));context_.setBounds(top);auto actions=r.removeFromBottom(40);for(auto*b:{&analyze_,&stop_,&confirm_,&focus_,&fork_,&approve_,&arm_})b->setBounds(actions.removeFromLeft(112).reduced(3));const bool show=processor_.uiSnapshot()->showProposalDrawer;proposal_.setBounds(r.removeFromRight(show?300:0));conversation_.setBounds(r);proposal_.setVisible(show);}void PluginEditor::timerCallback(){auto s=processor_.uiSnapshot();context_.setText(juce::String("Project: ")+s->scope.projectId+"  Track: "+s->scope.trackHint+"  Instance: "+s->scope.instanceId+(s->scope.confirmed?" [confirmed]":" [hint]"),juce::dontSendNotification);conversation_.setText(juce::String("Conversation / analysis: ")+s->analysis,juce::dontSendNotification);fork_.setButtonText(s->forkConfirmation?"Confirm fork":"Fork session");auto scheduler=s->scheduler;auto countdown=s->countdownBeats;switch(processor_.generationStatus()){case GenerationUiStatus::waitingForTransport:scheduler="waiting_for_transport";break;case GenerationUiStatus::countdown:scheduler="countdown";countdown=processor_.generationCountdownBeats();break;case GenerationUiStatus::playing:scheduler="playing";break;case GenerationUiStatus::complete:scheduler="complete";break;case GenerationUiStatus::stopped:scheduler="stopped";break;case GenerationUiStatus::idle:break;}juce::String status(s->connection+" | "+s->session+" | "+s->fork+" | "+s->approval+" | "+scheduler);if(countdown>0)status<<" "<<juce::String(countdown,1)<<" beats";status_.setText(status,juce::dontSendNotification);juce::String proposal;if(s->proposal)proposal<<"Proposal "<<s->proposal->proposalId<<" r"<<static_cast<juce::int64>(s->proposal->revision)<<" ["<<s->proposal->kind<<"]\nScope: "<<s->proposal->projectId<<" / "<<s->proposal->instanceId<<" / "<<s->proposal->clipSid<<"\n"<<s->proposal->rationale<<"\nAssumptions: "<<s->proposal->assumptionsSummary<<"\nMaterial: "<<s->proposal->materialSummary;proposal_.setText(proposal,juce::dontSendNotification);resized();}
}
